//! Material stories (`Engine/Materials/*` beyond the basics): blend modes, alpha mask, normal and PBR maps, glTF import.
//!
//! Owner: P-MAT (graphics spec §3.6). Every texture is generated in code, except the test ship
//! (`assets/ship.glb`, regenerated by `space3d-assets`' `gltf_materials` test).

use super::{CLEAR, ambient, camera, mesh, screen_target, sun};
use crate::{KnobValues, Story};
use space3d_assets::render::{ModelUploadOptions, spawn_model, upload_model};
use space3d_core::glam::EulerRot;
use space3d_core::prelude::*;
use space3d_render::{
    AddressMode, BlendMode, Camera3d, FilterMode, LightingSettings, MapMask, Material, Mesh3d, MeshExtras, PointLight,
    Projection, RenderAssets, RenderTarget, RenderTargetDesc, SamplerSettings, ShadingModel, TextureHandle,
    TextureSource, TextureTransform,
};

/// This area's stories, in registry order.
pub(crate) fn stories() -> Vec<Story> {
    vec![blend_modes(), alpha_mask(), normal_maps(), pbr_maps(), gltf_ship()]
}

/// The test ship: a hull with baked base color, normal, ORM and emissive maps.
const SHIP_GLB: &[u8] = include_bytes!("../../assets/ship.glb");

fn lighting(app: &mut App, k: &KnobValues) {
    let shading = if k.choice("shading") == 1 {
        ShadingModel::Standard
    } else {
        ShadingModel::Classic
    };
    app.insert_resource(LightingSettings {
        shading,
        normal_maps: k.bool("normal_maps"),
        ..LightingSettings::default()
    });
}

fn texture(app: &mut App, source: TextureSource) -> TextureHandle {
    app.resources.init::<RenderAssets>().add_texture(source)
}

/// Encode a unit tangent-space normal as linear RGBA8.
fn encode_normal(n: Vec3) -> [u8; 4] {
    let e = |c: f32| ((c * 0.5 + 0.5) * 255.0).round() as u8;
    [e(n.x), e(n.y), e(n.z), 255]
}

/// Panel maps (64²): a normal map of bevelled panels with rivets, and the matching ORM map
/// (occlusion in the seams, rough seams, metallic panels with a dielectric stripe) — linear.
fn panel_maps() -> (ImageData, ImageData) {
    const N: u32 = 64;
    let height = |x: i32, y: i32| -> f32 {
        let (gx, gy) = (x.rem_euclid(16), y.rem_euclid(16));
        let edge = gx.min(15 - gx).min(gy.min(15 - gy)) as f32;
        let mut h = (edge / 2.0).min(1.0);
        if (gx == 4 || gx == 11) && (gy == 4 || gy == 11) {
            h += 0.5;
        }
        h
    };
    let mut normal = ImageData::new(N, N);
    let mut orm = ImageData::new(N, N);
    for y in 0..N {
        for x in 0..N {
            let (xi, yi) = (x as i32, y as i32);
            // +X right, +Y up (rows go down).
            let dx = (height(xi + 1, yi) - height(xi - 1, yi)) * 0.5;
            let dy = -(height(xi, yi + 1) - height(xi, yi - 1)) * 0.5;
            normal.set(x, y, encode_normal(Vec3::new(-dx * 2.0, -dy * 2.0, 1.0).normalize()));
            let h = height(xi, yi).min(1.0);
            let stripe = (24..32).contains(&y);
            orm.set(
                x,
                y,
                [
                    (90.0 + 165.0 * h) as u8,
                    if h < 0.99 { 235 } else { 110 },
                    if stripe { 20 } else { 235 },
                    255,
                ],
            );
        }
    }
    (normal, orm)
}

/// Five quads over a checkered, color-barred backdrop, one per blend mode, each a
/// half-transparent color (the alpha-masked one cut by a disc), plus two overlapping
/// alpha-blended quads whose `render_order` decides which one draws last.
fn blend_modes() -> Story {
    Story::new("Engine/Materials/Blend Modes", |app, k| {
        let quad = mesh(app, MeshData::plane(1.0));
        let backdrop = app
            .resources
            .init::<RenderAssets>()
            .add_image(ImageData::checker(64, 8, [200, 200, 200, 255], [60, 60, 70, 255]));
        let up = Quat::from_rotation_x(std::f32::consts::FRAC_PI_2);
        app.world.spawn((
            Name("backdrop".into()),
            Transform::from_xyz(0.0, 0.0, -1.0)
                .with_rotation(up)
                .with_scale(Vec3::new(7.0, 1.0, 3.6)),
            Mesh3d(quad),
            Material::unlit(Vec4::ONE).with_texture(backdrop),
        ));
        for (i, c) in [[0.9, 0.1, 0.1], [0.1, 0.8, 0.2], [0.15, 0.3, 0.95]].into_iter().enumerate() {
            app.world.spawn((
                Transform::from_xyz(0.0, 1.1 - i as f32 * 0.35, -0.9)
                    .with_rotation(up)
                    .with_scale(Vec3::new(7.0, 1.0, 0.14)),
                Mesh3d(quad),
                Material::unlit(Vec3::from_array(c).extend(1.0)),
            ));
        }
        let alpha = k.f32("alpha");
        let color = Vec3::new(1.0, 0.55, 0.1);
        // A disc in the alpha channel for the mask.
        let mut disc = ImageData::new(32, 32);
        for y in 0..32 {
            for x in 0..32 {
                let d = ((x as f32 - 15.5).powi(2) + (y as f32 - 15.5).powi(2)).sqrt() / 16.0;
                disc.set(x, y, [255, 255, 255, ((1.0 - d).clamp(0.0, 1.0) * 255.0) as u8]);
            }
        }
        let disc = texture(app, TextureSource::from_image(disc));
        let modes = [
            (BlendMode::Opaque, "opaque"),
            (BlendMode::AlphaMask, "alpha mask"),
            (BlendMode::AlphaBlend, "alpha blend"),
            (BlendMode::Premultiplied, "premultiplied"),
            (BlendMode::Additive, "additive"),
        ];
        for (i, (mode, name)) in modes.into_iter().enumerate() {
            let rgb = if mode == BlendMode::Premultiplied {
                color * alpha
            } else {
                color
            };
            let a = if mode == BlendMode::Opaque { 1.0 } else { alpha };
            let mut material = Material::unlit(rgb.extend(a)).with_blend(mode);
            if mode == BlendMode::AlphaMask {
                material = material.with_texture(disc).with_alpha_mask(k.f32("cutoff"));
                material.base_color.w = 1.0;
            }
            app.world.spawn((
                Name(name.into()),
                Transform::from_xyz(i as f32 * 1.3 - 2.6, 0.55, 0.0)
                    .with_rotation(up)
                    .with_scale(Vec3::splat(1.1)),
                Mesh3d(quad),
                material,
            ));
        }
        // Render order: the red quad draws after the blue one with `red_on_top`.
        let order = if k.bool("red_on_top") { 1 } else { -1 };
        for (i, (rgb, o)) in [(Vec3::new(1.0, 0.1, 0.1), order), (Vec3::new(0.1, 0.4, 1.0), 0)]
            .into_iter()
            .enumerate()
        {
            app.world.spawn((
                Transform::from_xyz(-0.35 + i as f32 * 0.7, -0.95, 0.1)
                    .with_rotation(up)
                    .with_scale(Vec3::new(1.2, 1.0, 0.8)),
                Mesh3d(quad),
                Material::unlit(rgb.extend(0.65))
                    .with_blend(BlendMode::AlphaBlend)
                    .with_render_order(o),
            ));
        }
        camera(
            app,
            Vec3::new(0.0, 0.0, 6.0),
            Vec3::ZERO,
            Projection::Orthographic {
                height: 3.6,
                near: 0.1,
                far: 20.0,
            },
        );
    })
    .description(
        "The five blend modes over a checkered backdrop, left to right: opaque, alpha mask (a disc cut at `cutoff`), alpha blend, premultiplied (color × alpha \
         stored) and additive (brightens, keeps destination alpha). Below, two overlapping \
         alpha-blended quads ordered by `Material::render_order` (`red_on_top`).",
    )
    .knob_f32("alpha", 0.5, 0.0..=1.0)
    .knob_f32("cutoff", 0.5, 0.0..=1.0)
    .knob_bool("red_on_top", true)
    .size(360, 180)
}

/// Cut-out foliage: an alpha-masked, double-sided card whose alpha keeps a lattice of leaves (the
/// rest is cut away), seen at an angle over a lit backdrop, rendered into a render target with 1
/// or 4 samples (with 4, the mask becomes alpha to coverage: smooth edges).
fn alpha_mask() -> Story {
    Story::new("Engine/Materials/Alpha Mask", |app, k| {
        let samples = if k.choice("msaa") == 1 { 4 } else { 1 };
        let rt = screen_target(
            app,
            RenderTargetDesc::default().with_samples(samples),
            Vec3::new(0.0, -100.0, 0.0),
            CLEAR,
        );
        // Alpha: leaf-shaped blobs on a 4 × 4 lattice (smooth edges, so the cutoff moves them).
        const N: u32 = 128;
        let mut leaves = ImageData::new(N, N);
        for y in 0..N {
            for x in 0..N {
                let (u, v) = (x as f32 / N as f32 * 4.0, y as f32 / N as f32 * 4.0);
                let (fu, fv) = (u.fract() - 0.5, v.fract() - 0.5);
                let r = std::f32::consts::FRAC_1_SQRT_2;
                let (a, b) = ((fu + fv) * r, (fu - fv) * r);
                let d = ((a / 0.42).powi(2) + (b / 0.2).powi(2)).sqrt();
                let alpha = ((1.2 - d) * 1.6).clamp(0.0, 1.0);
                let g = (150.0 + 80.0 * (1.0 - d).clamp(0.0, 1.0)) as u8;
                leaves.set(x, y, [60, g, 40, (alpha * 255.0) as u8]);
            }
        }
        let leaves = texture(app, TextureSource::from_image(leaves));
        let quad = mesh(app, MeshData::plane(3.0));
        let backdrop = mesh(app, MeshData::plane(12.0));
        app.world.spawn((
            Name("leaves".into()),
            Transform::from_xyz(0.0, 0.0, 0.0).with_rotation(Quat::from_euler(EulerRot::YXZ, 0.5, 1.2, 0.0)),
            Mesh3d(quad),
            Material {
                double_sided: true,
                ..Material::color(Vec4::ONE)
                    .with_texture(leaves)
                    .with_alpha_mask(k.f32("cutoff"))
            },
        ));
        app.world.spawn((
            Transform::from_xyz(0.0, -1.2, 0.0),
            Mesh3d(backdrop),
            Material::srgb(0.25, 0.22, 0.3).with_metallic_roughness(0.0, 0.9),
        ));
        sun(app, Vec3::new(-0.4, -1.0, -0.5), 2.2);
        ambient(app, 0.15);
        app.world.spawn((
            Name("scene camera".into()),
            Transform::from_xyz(0.0, 1.6, 3.6).looking_at(Vec3::new(0.0, -0.2, 0.0), Vec3::Y),
            Camera3d {
                order: -1,
                ..Camera3d::default()
                    .with_clear_color(CLEAR)
                    .with_target(RenderTarget::Texture(rt))
            },
        ));
    })
    .description(
        "An alpha-masked, double-sided card whose alpha keeps a lattice of leaves (`cutoff` \
         shrinks or grows them) over a backdrop: the cut-away parts write no depth, so what is \
         behind shows through. With `msaa` 4× the mask becomes alpha to coverage — smooth, \
         sort-free edges; 1× discards (aliased edges).",
    )
    .knob_f32("cutoff", 0.5, 0.05..=0.95)
    .knob_choice("msaa", &["1x (discard)", "4x (alpha to coverage)"], 1)
    .size(320, 200)
}

/// A panel-mapped quad and cube under a sun at a knob angle: the normal map on vertex
/// (MikkTSpace) or per-pixel tangent frames, with its scale on a knob.
fn normal_maps() -> Story {
    Story::new("Engine/Materials/Normal Maps", |app, k| {
        lighting(app, k);
        let (normal, _) = panel_maps();
        let map = texture(app, TextureSource::from_image_linear(normal));
        let vertex = k.choice("tangents") == 0;
        let add = |app: &mut App, data: MeshData| {
            if vertex {
                let (data, tangents) = space3d_assets::edit::mesh::compute_mikktspace_tangents(&data);
                app.resources
                    .init::<RenderAssets>()
                    .add_mesh_with(data, MeshExtras::new().with_tangents(tangents))
            } else {
                mesh(app, data)
            }
        };
        let cube = add(app, MeshData::cube(1.4));
        let plane = add(app, MeshData::plane(2.4));
        let material = Material::color(Vec4::new(0.75, 0.72, 0.68, 1.0))
            .with_metallic_roughness(0.0, 0.45)
            .with_normal_map(map, k.f32("normal_scale"));
        app.world.spawn((
            Name("panel".into()),
            Transform::from_xyz(-1.4, 0.0, 0.0).with_rotation(Quat::from_rotation_x(1.2)),
            Mesh3d(plane),
            material.clone(),
        ));
        app.world.spawn((
            Name("cube".into()),
            Transform::from_xyz(1.3, 0.0, 0.0).with_rotation(Quat::from_euler(EulerRot::YXZ, 0.6, 0.45, 0.0)),
            Mesh3d(cube),
            material,
        ));
        let a = k.f32("light_angle").to_radians();
        sun(app, Vec3::new(a.sin(), -0.6, -a.cos()), 1.3);
        ambient(app, 0.06);
        camera(app, Vec3::new(0.0, 0.4, 4.6), Vec3::ZERO, Projection::default());
    })
    .description(
        "Bevelled panels with rivets from a normal map on a quad and a cube (`tangents` switches \
         between MikkTSpace vertex tangents and per-pixel frames: they agree), lit by a sun at \
         `light_angle`.",
    )
    .knob_choice("tangents", &["Vertex (MikkTSpace)", "Per pixel"], 0)
    .knob_f32("normal_scale", 1.0, 0.0..=3.0)
    .knob_f32("light_angle", 40.0, -180.0..=180.0)
    .knob_choice("shading", &["Classic", "Standard"], 0)
    .knob_bool("normal_maps", true)
    .size(320, 200)
}

/// A PBR ball grid: roughness left → right; rows top to bottom metal, dielectric, and mapped
/// (ORM + normal + emissive; the maps multiply the row's factors).
fn pbr_maps() -> Story {
    Story::new("Engine/Materials/PBR Maps", |app, k| {
        lighting(app, k);
        let (normal, orm) = panel_maps();
        let normal = texture(app, TextureSource::from_image_linear(normal));
        let orm = texture(app, TextureSource::from_image_linear(orm));
        let mut glow = ImageData::new(64, 32);
        for y in 0..32 {
            for x in 0..64 {
                let band = (13..19).contains(&y) && x % 8 < 5;
                glow.set(x, y, if band { [255, 150, 40, 255] } else { [0, 0, 0, 255] });
            }
        }
        let glow = texture(
            app,
            TextureSource {
                sampler: SamplerSettings {
                    filter: FilterMode::Linear,
                    address: AddressMode::Repeat,
                },
                ..TextureSource::from_image(glow)
            },
        );
        let sphere = MeshData::sphere(0.42, 48, 24);
        let (mapped, tangents) = space3d_assets::edit::mesh::compute_mikktspace_tangents(&sphere);
        let sphere = mesh(app, sphere);
        let mapped = app
            .resources
            .init::<RenderAssets>()
            .add_mesh_with(mapped, MeshExtras::new().with_tangents(tangents));
        let tiling = TextureTransform {
            scale: Vec2::new(4.0, 2.0),
            ..TextureTransform::IDENTITY
        };
        let columns = 4;
        for row in 0..3 {
            for col in 0..columns {
                let roughness = 0.12 + 0.8 * col as f32 / (columns - 1) as f32;
                let (base, metallic) = match row {
                    0 => (Vec4::new(0.95, 0.72, 0.38, 1.0), 1.0),
                    1 => (Vec4::new(0.7, 0.08, 0.06, 1.0), 0.0),
                    _ => (Vec4::new(0.8, 0.82, 0.86, 1.0), 1.0),
                };
                let mut material = Material::color(base).with_metallic_roughness(metallic, roughness);
                let mut m = sphere;
                if row == 2 {
                    m = mapped;
                    material = material
                        .with_normal_map(normal, k.f32("normal_scale"))
                        .with_orm_map(orm)
                        .with_emissive_map(glow, Vec3::splat(k.f32("emissive")))
                        .with_uv_transform(tiling);
                    material.roughness = 0.5 + roughness * 0.5;
                    material.occlusion_strength = k.f32("occlusion");
                }
                app.world.spawn((
                    Transform::from_xyz(col as f32 - 1.5, 1.0 - row as f32, 0.0),
                    Mesh3d(m),
                    material,
                ));
            }
        }
        sun(app, Vec3::new(0.5, -0.6, -1.0), 2.0);
        app.world.spawn((
            Transform::from_xyz(-2.5, 2.0, 2.5),
            PointLight {
                color: Vec3::new(0.7, 0.8, 1.0),
                intensity: 9.0,
                range: 12.0,
            },
        ));
        ambient(app, 0.25);
        camera(app, Vec3::new(0.0, 0.0, 4.4), Vec3::ZERO, Projection::default());
    })
    .description(
        "Ball grid, roughness left → right: a metal row, a dielectric row and a mapped row — \
         ORM-packed occlusion-roughness-metallic (the maps multiply the factors), a panel normal \
         map on MikkTSpace tangents and an emissive band, tiled by the material's UV transform. \
         Knobs: shading model, normal maps on/off, normal scale, occlusion strength, emissive.",
    )
    .knob_choice("shading", &["Classic", "Standard"], 0)
    .knob_bool("normal_maps", true)
    .knob_f32("normal_scale", 1.0, 0.0..=3.0)
    .knob_f32("occlusion", 1.0, 0.0..=1.0)
    .knob_f32("emissive", 1.5, 0.0..=4.0)
    .size(320, 256)
}

/// The in-tree test ship through the whole glTF path: `load_gltf` → `upload_model` (MikkTSpace
/// tangents generated, textures in their color spaces and samplers) → `spawn_model`.
fn gltf_ship() -> Story {
    Story::new("Engine/Materials/glTF Import", |app, k| {
        lighting(app, k);
        let model = space3d_assets::loaders::load_gltf(SHIP_GLB, &space3d_assets::LoadContext::new("ship.glb"), true)
            .expect("ship.glb decodes");
        let assets = app.resources.init::<RenderAssets>();
        let mut uploaded = upload_model(&model, assets, &ModelUploadOptions::default());
        if !k.bool("maps") {
            // Base color only: what the game drew before material maps.
            for part in &mut uploaded.parts {
                let m = &mut part.material;
                m.normal_texture = None;
                m.metallic_roughness_texture = None;
                m.occlusion_texture = None;
                m.emissive_texture = None;
                m.emissive = Vec3::ZERO;
                m.uv1_maps = MapMask::NONE;
            }
        }
        let yaw = k.f32("yaw").to_radians();
        spawn_model(
            &mut app.world,
            &uploaded,
            Transform::IDENTITY.with_rotation(Quat::from_rotation_y(yaw)),
        );
        sun(app, Vec3::new(-0.35, -1.0, -0.3), 2.6);
        app.world.spawn((
            Transform::from_xyz(2.0, 1.4, 1.6),
            PointLight {
                color: Vec3::new(0.35, 0.6, 1.0),
                intensity: 8.0,
                range: 6.0,
            },
        ));
        ambient(app, 0.2);
        camera(
            app,
            Vec3::new(2.3, 3.2, 2.5),
            Vec3::new(0.0, -0.3, 0.0),
            Projection::default(),
        );
    })
    .description(
        "The test ship `assets/ship.glb` (baked base color, normal, ORM-packed \
         occlusion-roughness-metallic and emissive maps, no TANGENT) straight from glTF: \
         MikkTSpace tangents are generated on upload, base color and emissive are sRGB, the data \
         maps linear, the emissive factor × `KHR_materials_emissive_strength` 4. `maps` off shows \
         the base-color-only look.",
    )
    .knob_bool("maps", true)
    .knob_f32("yaw", -140.0, -180.0..=180.0)
    .knob_choice("shading", &["Classic", "Standard"], 0)
    .knob_bool("normal_maps", true)
    .size(320, 240)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::space3d_test::{CompareOptions, compare_images, require_gpu};
    use crate::{KnobValue, run_story_headless};

    /// The two tangent frames of the normal-map story agree (MikkTSpace vertex tangents on a
    /// cube and a plane vs per-pixel derivative frames), and the maps change the picture.
    #[test]
    fn tangent_sources_agree_and_maps_matter() {
        require_gpu!();
        let story = normal_maps();
        let vertex = run_story_headless(&story, &KnobValues::default(), None).unwrap();
        let per_pixel = KnobValues::default().with("tangents", KnobValue::Choice(1));
        let per_pixel = run_story_headless(&story, &per_pixel, None).unwrap();
        let stats = compare_images(&vertex, &per_pixel, &CompareOptions::perceptual());
        assert!(stats.passed, "vertex vs per-pixel tangents: {}", stats.summary());
        let flat = KnobValues::default().with("normal_maps", KnobValue::Bool(false));
        let flat = run_story_headless(&story, &flat, None).unwrap();
        assert!(!compare_images(&vertex, &flat, &CompareOptions::default()).passed);
        // Alpha to coverage (4×) smooths the mask's edges that 1× discards.
        let mask = alpha_mask();
        let a2c = run_story_headless(&mask, &KnobValues::default(), None).unwrap();
        let discard = KnobValues::default().with("msaa", KnobValue::Choice(0));
        let discard = run_story_headless(&mask, &discard, None).unwrap();
        assert!(!compare_images(&a2c, &discard, &CompareOptions::exact()).passed);
        // The ship with and without its maps differs too.
        let ship = gltf_ship();
        let mapped = run_story_headless(&ship, &KnobValues::default(), None).unwrap();
        let plain = KnobValues::default().with("maps", KnobValue::Bool(false));
        let plain = run_story_headless(&ship, &plain, None).unwrap();
        assert!(!compare_images(&mapped, &plain, &CompareOptions::default()).passed);
    }
}
